using Microsoft.Extensions.Options; using PiSignalWatch.Config; using PiSignalWatch.Models; using PiSignalWatch.Processing; using PiSignalWatch.Storage;
public class StorageDigestTests{[Fact] public async Task WritesJson(){var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString()); var s=new JsonFileStorageProvider(Options.Create(new AppSettings{DataFolder=dir})); await s.SaveProcessedItemsAsync([new(){Source=new(){Title="x"}}],default); Assert.True(Directory.GetFiles(Path.Combine(dir,"processed")).Length>0);} [Fact] public void BuildsDigest(){var d=new DigestBuilder(); var dg=d.Build([new(){Source=new(){Title="x"}}]); Assert.Single(dg.Items);} }
